namespace Jobsy.Core.Careers;

/// <summary>
/// Plain-language breakdown of one job-fit percent. Built from <see cref="CareerCompassBuilder.MatchMath"/>,
/// the same path as the number on screen. Never generated by a model.
/// </summary>
public sealed class FitPercentExplanation
{
    public const string SourceName = "O*NET 31.0";
    public const string EscoVersion = "ESCO v1.2.1";

    private FitPercentExplanation(
        string title,
        decimal percent,
        decimal weightSum,
        decimal productSum,
        IReadOnlyList<ProfileMatchTerm> terms,
        string escoId,
        IReadOnlyList<string> onetCodes,
        string confidence,
        string education,
        bool hasEducationGate,
        bool extraTraining,
        bool aboveLevel,
        bool officeSwap)
    {
        Title = title;
        Percent = percent;
        WeightSum = weightSum;
        ProductSum = productSum;
        Terms = terms;
        EscoId = escoId;
        OnetCodes = onetCodes;
        Confidence = confidence;
        Education = education;
        HasEducationGate = hasEducationGate;
        ExtraTraining = extraTraining;
        AboveLevel = aboveLevel;
        OfficeSwap = officeSwap;
    }

    public string Title { get; }
    public decimal Percent { get; }
    public decimal WeightSum { get; }
    public decimal ProductSum { get; }
    public IReadOnlyList<ProfileMatchTerm> Terms { get; }
    public string EscoId { get; }
    public IReadOnlyList<string> OnetCodes { get; }
    public string Confidence { get; }
    public string Education { get; }
    public bool HasEducationGate { get; }
    public bool ExtraTraining { get; }
    public bool AboveLevel { get; }
    public bool OfficeSwap { get; }

    public string Equation
        => WeightSum <= 0m
            ? CareerCompassBuilder.FormatPercent(Percent)
            : $"{Num(ProductSum)} / {Num(WeightSum)} = {CareerCompassBuilder.FormatPercent(Percent)}";

    /// <summary>
    /// Explanation for a catalogue title that has a shown percent. Null when that title has no percent.
    /// <paramref name="education"/> does not change the number. It only fills the filter paragraph.
    /// </summary>
    public static FitPercentExplanation? Build(string title, RiasecScores scores, string? education = null)
    {
        var occupation = OccupationCatalog.Shared.Resolve(title);
        if (occupation is not { IsListable: true, Oi: { Count: 6 } oi })
        {
            return null;
        }

        var math = CareerCompassBuilder.MatchMath(oi, scores);
        var gate = CareerEducationGate.MaxIscoLevel(education);
        var shownEducation = (education ?? "").Trim();
        var hasGate = gate.HasGate && shownEducation.Length > 0;
        var extra = hasGate && CareerEducationGate.NeedsExtraTraining(occupation.IscoLevel, gate);
        var above = hasGate && !CareerEducationGate.Passes(occupation.IscoLevel, gate);
        var swap = hasGate
                   && gate.SubstituteLowerOffice
                   && OccupationCatalog.Shared.LevelSwaps.Any(item =>
                       string.Equals(item.FromId, occupation.Id, StringComparison.OrdinalIgnoreCase));

        return new FitPercentExplanation(
            occupation.Nl,
            math.Percent,
            math.WeightSum,
            math.ProductSum,
            math.Terms,
            occupation.Id,
            occupation.Onet,
            occupation.Confidence,
            shownEducation,
            hasGate,
            extra,
            above,
            swap);
    }

    public static RiasecScores? TryScores(string? fingerprint)
    {
        if (string.IsNullOrWhiteSpace(fingerprint))
        {
            return null;
        }

        var parts = fingerprint.Split('|');
        if (parts.Length != 6)
        {
            return null;
        }

        var values = new int?[6];
        for (var i = 0; i < 6; i++)
        {
            if (!int.TryParse(parts[i], NumberStyles.Integer, CultureInfo.InvariantCulture, out var value))
            {
                return null;
            }

            values[i] = value;
        }

        return TryScores(values[0], values[1], values[2], values[3], values[4], values[5]);
    }

    public static RiasecScores? TryScores(int? realistic, int? investigative, int? artistic, int? social, int? enterprising, int? conventional)
    {
        var scores = new RiasecScores(realistic, investigative, artistic, social, enterprising, conventional);
        return scores.IsComplete ? scores : null;
    }

