    public static string Render(FitPercentExplanation explain, string? lang)
        => string.Join("\n", Lines(explain, lang));

    public static IReadOnlyList<string> Lines(FitPercentExplanation explain, string? lang)
    {
        var code = JobsyLanguages.Normalize(lang);
        var lines = new List<string>
        {
            Intro(code, explain.Title),
            ScoresHeading(code)
        };
        foreach (var term in explain.Terms.Where(term => term.Weight > 0m))
        {
            lines.Add(ScoreLine(code, term));
        }

        lines.Add(ProfileHeading(code));
        foreach (var term in explain.Terms)
        {
            lines.Add(ProfileLine(code, term));
        }

        lines.Add(SourceLine(code, explain));
        lines.Add(ConfidenceLine(code, explain.Confidence));
        lines.Add(Formula(code));
        lines.Add(FilledHeading(code));
        foreach (var term in explain.Terms.Where(term => term.Weight > 0m))
        {
            lines.Add($"{Num(term.Weight, code)} × {term.Score} = {Num(term.Product, code)}");
        }

        lines.Add(EquationFor(explain, code));
        if (explain.HasEducationGate)
        {
            lines.Add(EducationLine(code, explain.Education));
            if (explain.ExtraTraining)
            {
                lines.Add(ExtraLine(code));
            }

            if (explain.AboveLevel)
            {
                lines.Add(AboveLine(code));
            }

            if (explain.OfficeSwap)
            {
                lines.Add(SwapLine(code));
            }
        }

        return lines;
    }

    /// <summary>Short PDF note. Same numbers as <see cref="Render"/>, without the full worked lines.</summary>
    public static string Footnote(IReadOnlyList<FitPercentExplanation> items, string? lang)
    {
        if (items.Count == 0)
        {
            return FormulaOnly(lang);
        }

        var code = JobsyLanguages.Normalize(lang);
        var sb = new StringBuilder();
        sb.Append(FormulaOnly(code));
        if (items.Any(item => item.HasEducationGate))
        {
            sb.Append(' ');
            sb.Append(EducationUnchanged(code));
        }

        foreach (var item in items)
        {
            sb.AppendLine();
            sb.Append(JobLine(code, item));
        }

        return sb.ToString().Trim();
    }

    /// <summary>Formula in words when the PDF has percents but no stored scores to fill in.</summary>
