    {
        "en" => "The percentage is a weighted average of your scores. A direction counts more when this job asks for it more. Source: O*NET 31.0. Subtract 1 from the O*NET number. That is the weight. Add weight times your score, divide by the sum of the weights, and round to 2 decimals.",
        "pl" => "Procent to średnia ważona twoich wyników. Kierunek liczy się bardziej, gdy zawód bardziej go wymaga. Źródło: O*NET 31.0. Odejmij 1 od liczby O*NET. To jest waga. Suma waga × twój wynik, podzielona przez sumę wag, zaokrąglona do 2 miejsc.",
        "ro" => "Procentul este o medie ponderată a scorurilor tale. O direcție contează mai mult când meseria o cere mai mult. Sursă: O*NET 31.0. Scazi 1 din numărul O*NET. Asta este ponderea. Suma pondere × scorul tău, împărțită la suma ponderilor, rotunjită la 2 zecimale.",
        "ar" => "النسبة هي متوسط مرجّح لدرجاتك. الاتجاه الذي تطلبه المهنة أكثر له وزن أكبر. المصدر: O*NET 31.0. نطرح 1 من رقم O*NET. هذا هو الوزن. مجموع الوزن × درجتك، مقسوماً على مجموع الأوزان، مع التقريب إلى منزلتين.",
        _ => "Het percentage is een gewogen gemiddelde van jouw scores. Een richting telt zwaarder als dit beroep die meer vraagt. Bron: O*NET 31.0. We trekken 1 af van het O*NET-getal. Dat is het gewicht. Som van gewicht × jouw score, gedeeld door de som van de gewichten, afgerond op 2 decimalen."
    };

    public static string Num(decimal value)
        => value.ToString("0.##", CultureInfo.InvariantCulture);

    public static string Num(decimal value, string? lang)
    {
        var code = JobsyLanguages.Normalize(lang);
        return code is "nl" or "pl" or "ro"
            ? value.ToString("0.##", CultureInfo.GetCultureInfo("nl-NL"))
            : Num(value);
    }

    private static string EquationFor(FitPercentExplanation explain, string? lang)
        => explain.WeightSum <= 0m
            ? CareerCompassBuilder.FormatPercent(explain.Percent, lang)
            : $"{Num(explain.ProductSum, lang)} / {Num(explain.WeightSum, lang)} = {CareerCompassBuilder.FormatPercent(explain.Percent, lang)}";

