    private static string ProfileLine(string lang, ProfileMatchTerm term)
    {
        var name = $"{Label(term.Code, lang)} ({Letter(term.Code)}): {Num(term.Oi)}";
        if (term.Weight <= 0m)
        {
            return lang switch
            {
                "en" => $"{name}. Weight 0, left out.",
                "pl" => $"{name}. Waga 0, nie liczy się.",
                "ro" => $"{name}. Pondere 0, nu intră în calcul.",
                "ar" => $"{name}. الوزن 0، لا يُحسب.",
                _ => $"{name}. Gewicht 0, telt niet mee."
            };
        }

        return lang switch
        {
            "en" => $"{name}. Weight {Num(term.Weight)}.",
            "pl" => $"{name}. Waga {Num(term.Weight)}.",
            "ro" => $"{name}. Pondere {Num(term.Weight)}.",
            "ar" => $"{name}. الوزن {Num(term.Weight)}.",
            _ => $"{name}. Gewicht {Num(term.Weight)}."
        };
    }

    private static string SourceLine(string lang, FitPercentExplanation explain)
    {
        var codes = explain.OnetCodes.Count == 0
            ? ""
            : string.Join(", ", explain.OnetCodes);
        return lang switch
        {
            "en" => codes.Length == 0
                ? $"Source: O*NET 31.0. ESCO v1.2.1, code {explain.EscoId}."
                : $"Source: O*NET 31.0. ESCO v1.2.1, code {explain.EscoId}. O*NET code: {codes}.",
            "pl" => codes.Length == 0
                ? $"Źródło: O*NET 31.0. ESCO v1.2.1, kod {explain.EscoId}."
                : $"Źródło: O*NET 31.0. ESCO v1.2.1, kod {explain.EscoId}. Kod O*NET: {codes}.",
            "ro" => codes.Length == 0
                ? $"Sursă: O*NET 31.0. ESCO v1.2.1, cod {explain.EscoId}."
                : $"Sursă: O*NET 31.0. ESCO v1.2.1, cod {explain.EscoId}. Cod O*NET: {codes}.",
            "ar" => codes.Length == 0
                ? $"المصدر: O*NET 31.0. ESCO v1.2.1، الرمز {explain.EscoId}."
                : $"المصدر: O*NET 31.0. ESCO v1.2.1، الرمز {explain.EscoId}. رمز O*NET: {codes}.",
            _ => codes.Length == 0
                ? $"Bron: O*NET 31.0. ESCO v1.2.1, code {explain.EscoId}."
                : $"Bron: O*NET 31.0. ESCO v1.2.1, code {explain.EscoId}. O*NET-code: {codes}."
        };
    }

