    private static string JobLine(string lang, FitPercentExplanation item)
    {
        var codes = item.OnetCodes.Count == 0 ? "" : string.Join(", ", item.OnetCodes);
        var link = item.Confidence == "high"
            ? lang switch
            {
                "en" => "link high",
                "pl" => "powiązanie wysokie",
                "ro" => "legătură mare",
                "ar" => "ربط عالٍ",
                _ => "koppeling hoog"
            }
            : lang switch
            {
                "en" => "link medium",
                "pl" => "powiązanie średnie",
                "ro" => "legătură medie",
                "ar" => "ربط متوسط",
                _ => "koppeling gemiddeld"
            };
        var codePart = codes.Length == 0
            ? $"ESCO {item.EscoId}"
            : $"ESCO {item.EscoId}. O*NET {codes}";
        var extra = item.ExtraTraining || item.AboveLevel || item.OfficeSwap
            ? " " + EducationUnchanged(lang)
            : "";
        return $"{item.Title}: {item.Equation}. {codePart}. {link}.{extra}";
    }

    private static string Label(string code, string lang) => DimensionLabels.For(code, lang);

    private static string Letter(string code)
        => CareerTestCatalog.HollandLetter.TryGetValue(code, out var letter)
            ? letter.ToString()
            : code;
}
